webmcpTools.inputSchema:
{"type":"object","properties":{"action":{"type":"string","enum":["browserState","click","fill","select","scroll","executeJavascript"],"description":"执行的动作名称, 每一次执行 'click', 'fill', 'select'动作之前，**必须**要先调用 'browserState' 去获取页面的最新状态。 
        browserState: '查询整个页面的浏览器状态;返回页面的标题、URL、HTML内容',
        click: '根据元素索引点击;',
        fill: '根据元素索引填写文本;'; 
        select: '根据元素索引选择下拉框选项;'; 
        scroll: '滚动页面的动作，可以指定水平滚动还是上下滚动; 不带元素索引时：滚动整个文档。带元素索引时：滚动该索引处的容器（或其最近的可滚动祖先元素）'
        executeJavascript: '执行javascript代码'
    "},"index":{"type":"number","minimum":0,"description":"执行动作的元素索引, 动作为 click,fill,select时，必须提供元素索引"},"text":{"type":"string","description":"执行动作的文本内容, 动作为 fill,select 时，必须提供文本内容"},"down":{"type":"boolean","description":"执行上下滚动时，必须提供down参数"},"right":{"type":"boolean","description":"执行水平滚动方向, 必须提供right参数"},"numPages":{"type":"number","description":"执行动作的滚动页数, 动作为 scroll时，可以提供滚动页数，建议每次滚动0.1页，该值不要大于5."},"pixels":{"type":"integer","minimum":0,"description":"执行动作的滚动像素数，动作为 scroll时，可以提供滚动像素数"},"script":{"type":"string","description":"执行的javascript代码，动作为 executeJavascript时，必须提供script参数"}},"required":["action"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"}
